import { createHash, randomUUID } from "node:crypto";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";

/**
 * Blob storage for original media (ADR-006). Originals are stored exactly as received and are never
 * modified; the database keeps the SHA-256 and size so every read can be verified (AC-03).
 *
 * Keys are generated by the server only: "<legacy uuid>/<asset uuid>". User input never reaches a path.
 *
 * Adapters:
 *  - LocalBlobStore: a directory on the server's disk. Development and tests only. Refused on hosted
 *    deployments (Vercel's filesystem is not durable), like the development sign-in.
 *  - Supabase Storage: planned for the hosted preview (private bucket, server-side access only).
 */
export interface BlobStore {
  readonly name: string;
  put(key: string, bytes: Buffer): Promise<{ sha256: string; size: number }>;
  get(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
}

const KEY_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

export function sha256Hex(bytes: Buffer): string {
  return createHash("sha256").update(bytes).digest("hex");
}

export function assertKey(key: string): void {
  if (!KEY_RE.test(key)) throw new Error("Invalid storage key");
}

export class BlobNotFoundError extends Error {
  constructor() {
    super("blob_not_found");
  }
}

export class LocalBlobStore implements BlobStore {
  readonly name = "local";
  private readonly root: string;

  constructor(root: string) {
    this.root = resolve(root);
  }

  private path(key: string): string {
    assertKey(key);
    const p = resolve(this.root, ...key.split("/"));
    if (!p.startsWith(this.root + sep)) throw new Error("Invalid storage key");
    return p;
  }

  async put(key: string, bytes: Buffer) {
    const target = this.path(key);
    await mkdir(dirname(target), { recursive: true, mode: 0o700 });
    // Write to a temporary file then rename, so a crash never leaves a half-written original.
    const tmp = join(dirname(target), `.tmp-${randomUUID()}`);
    await writeFile(tmp, bytes, { mode: 0o600, flag: "wx" });
    await rename(tmp, target);
    return { sha256: sha256Hex(bytes), size: bytes.length };
  }

  async get(key: string) {
    try {
      return await readFile(this.path(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") throw new BlobNotFoundError();
      throw err;
    }
  }

  async delete(key: string) {
    await rm(this.path(key), { force: true });
  }
}

/** Mirrors auth-mode: the local disk store can never be used on a hosted deployment. */
export function storageBackend(env: Record<string, string | undefined> = process.env): "local" | "unconfigured" {
  const hosted = Boolean(env.VERCEL) || Boolean(env.ECHO_HOSTED);
  const backend = env.STORAGE_BACKEND ?? "local";
  return backend === "local" && !hosted ? "local" : "unconfigured";
}

let store: BlobStore | undefined;

export function getBlobStore(): BlobStore {
  if (!store) {
    if (storageBackend() !== "local") {
      throw new Error("No durable media storage is configured for this deployment.");
    }
    store = new LocalBlobStore(process.env.STORAGE_DIR ?? ".data/blobs");
  }
  return store;
}

export function setBlobStore(s: BlobStore | undefined) {
  store = s;
}
